import {kindNames,riskNames,topics,itemDate,filterItems} from './model.js';

const main=document.querySelector('#main-content');
const iconPaths={search:'<circle cx="9" cy="9" r="6"/><path d="m14 14 4 4"/>',external:'<path d="M7 4h9v9M16 4 4 16"/>',back:'<path d="M16 10H4m5-5-5 5 5 5"/>',down:'<path d="m5 8 5 5 5-5"/>',share:'<path d="M10 13V2m-4 4 4-4 4 4M4 10v7h12v-7"/>'};
const icon=name=>`<svg aria-hidden="true" viewBox="0 0 20 20">${iconPaths[name]||iconPaths.external}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?value.slice(0,10).replaceAll('-','.'):'未披露';
const shortDate=value=>`${Number(value.slice(5,7))}月${Number(value.slice(8,10))}日`;
function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?esc(u.href):'';}catch{return '';}}
const sourceNames={anthropic:'Anthropic',openai:'OpenAI',microsoft:'Microsoft Security',trail:'Trail of Bits',unit42:'Unit 42',checkpoint:'Check Point',embrace:'Embrace The Red',pillar:'Pillar Security',zenity:'Zenity Labs',aws:'AWS Security',pdf:'AI事鉴 · PDF',github:'GitHub Advisories',seebug:'Seebug'};
const sourceLabel=source=>sourceNames[source.id]||source.shortName||source.name;
let items=[],sources=[],meta={},lastHash=location.hash||'#/feed',returnHash='#/feed',filtersOpen=false,searchTimer,toastTimer;
let inputMethod='pointer';
function loadRead(){try{const data=JSON.parse(localStorage.getItem('ai-security-observer:v1:read')||'[]');return new Set(Array.isArray(data)?data:[]);}catch{return new Set();}}
const read=loadRead();
function rememberRead(id){if(read.has(id))return;read.add(id);try{localStorage.setItem('ai-security-observer:v1:read',JSON.stringify([...read]));}catch{}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2000);}
function route(){
 const hash=location.hash.replace(/^#\/?/,'')||'feed';const [path,query='']=hash.split('?');const params=new URLSearchParams(query);let [view,id='']=path.split('/');
 if(view==='bookmarks')view='feed';try{id=decodeURIComponent(id);}catch{id='';}
 return {view,id,params,q:params.get('q')||'',source:params.get('source')||'all',topic:params.get('topic')||'all',risk:params.get('risk')||'all',evidence:params.get('evidence')||'all',period:params.get('period')||'all',sort:params.get('sort')||'latest',unread:params.get('unread')==='1'};
}
function setParam(key,value,{replace=false}={}){
 const r=route();const defaults={q:'',source:'all',topic:'all',risk:'all',evidence:'all',period:'all',sort:'latest',unread:'0'};
 if(!value||value===defaults[key])r.params.delete(key);else r.params.set(key,value);
 const next=`#/${r.view}${r.params.size?'?'+r.params.toString():''}`;
 if(replace){history.replaceState(null,'',next);lastHash=next;render(true);}else location.hash=next;
}
function reset(){const next=`#/${route().view}`;filtersOpen=false;const panel=document.querySelector('.filter-panel');if(panel)panel.open=false;if(location.hash===next){render();}else location.hash=next;}
const itemUrl=item=>`#/item/${encodeURIComponent(item.id)}`;
function tags(item){return item.tags.slice(0,3).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('');}
function metadata(item,{withDate=false}={}){return `<div class="item-meta"><i class="source-dot" aria-hidden="true"></i><span>${esc(item.sourceName)}</span><span>·</span><span class="kind ${esc(item.kind)}">${kindNames[item.kind]}</span>${withDate?`<span>·</span><time datetime="${esc(itemDate(item))}">${date(itemDate(item))}</time>`:''}${item.evidence==='compilation'?'<span class="compilation-label">· PDF 汇编</span>':''}</div>`;}
function viewItems(view){return items.filter(item=>view==='incidents'?item.kind==='incident':view==='research'?item.kind!=='incident':true);}
function usedSources(view){const data=viewItems(view);return sources.map(source=>({...source,count:data.filter(item=>item.sourceId===source.id).length})).filter(source=>source.count>0).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));}
function sourceSidebar(r){const available=usedSources(r.view);return `<aside class="source-sidebar" aria-label="按来源筛选"><h2 class="sidebar-heading">浏览来源 <span>${available.length}</span></h2><button class="source-button ${r.source==='all'?'active':''}" data-action="source" data-value="all" aria-pressed="${r.source==='all'}">全部来源 <span>${viewItems(r.view).length}</span></button>${available.map(source=>`<button class="source-button ${r.source===source.id?'active':''}" data-action="source" data-value="${esc(source.id)}" aria-pressed="${r.source===source.id}">${esc(sourceLabel(source))}<span>${source.count}</span></button>`).join('')}<a class="sidebar-footer" href="#/sources">查看全部来源 <span>↗</span></a></aside>`;}
function filters(r){const sourceOptions=usedSources(r.view);return `<form class="filter-form" id="filter-form" role="search" aria-label="搜索和筛选情报"><div class="search-row"><label class="search-box" for="search-input">${icon('search')}<input type="search" id="search-input" autocomplete="off" aria-label="搜索标题或内容" placeholder="搜索标题、内容或 CVE 编号…" value="${esc(r.q)}"></label><label class="mobile-source"><select class="select" id="source-filter" data-filter="source" aria-label="按来源筛选"><option value="all">全部来源</option>${sourceOptions.map(source=>`<option value="${esc(source.id)}" ${r.source===source.id?'selected':''}>${esc(sourceLabel(source))} (${source.count})</option>`).join('')}</select></label><details class="filter-panel" ${filtersOpen?'open':''}><summary>筛选 ${icon('down')}</summary><div class="filter-controls"><label>资料类型<select class="select" data-filter="evidence" aria-label="按来源证据筛选"><option value="all" ${r.evidence==='all'?'selected':''}>全部资料</option><option value="primary" ${r.evidence==='primary'?'selected':''}>一手披露</option><option value="compilation" ${r.evidence==='compilation'?'selected':''}>PDF 汇编</option></select></label><label>时间范围<select class="select" data-filter="period" aria-label="按时间范围筛选"><option value="all" ${r.period==='all'?'selected':''}>全部时间</option><option value="7" ${r.period==='7'?'selected':''}>最近 7 天</option><option value="30" ${r.period==='30'?'selected':''}>最近 30 天</option><option value="90" ${r.period==='90'?'selected':''}>最近 90 天</option></select></label><label>排序<select class="select" data-filter="sort" aria-label="排序方式"><option value="latest" ${r.sort==='latest'?'selected':''}>最新在前</option><option value="oldest" ${r.sort==='oldest'?'selected':''}>最早在前</option></select></label><label class="toggle-unread"><input type="checkbox" id="unread-toggle" ${r.unread?'checked':''}>只看未读</label><button class="filter-reset" type="button" data-action="reset">清空筛选</button></div></details></div><div class="topic-row" aria-label="主题筛选">${topics.map(topic=>`<button type="button" class="topic-button ${r.topic===topic.id?'active':''}" data-action="topic" data-value="${topic.id}" aria-pressed="${r.topic===topic.id}">${topic.label}</button>`).join('')}</div>${r.risk!=='all'?`<div class="active-risk">${esc(riskNames[r.risk]||r.risk)}<button type="button" data-action="risk-reset" aria-label="取消风险筛选">×</button></div>`:''}</form>`;}
function article(item){const original=item.references.find(ref=>ref.role==='primary'&&safeUrl(ref.url));return `<article class="news-item ${read.has(item.id)?'is-read':''}" data-item-id="${esc(item.id)}">${metadata(item)}<h2><a class="news-title" href="${itemUrl(item)}">${esc(item.title)}</a></h2><p class="news-summary">${esc(item.summary)}</p><div class="news-footer"><div class="item-tags">${tags(item)}</div><div class="article-links">${original?`<a href="${safeUrl(original.url)}" target="_blank" rel="noopener noreferrer">阅读原文 ${icon('external')}</a>`:''}<a href="${itemUrl(item)}">详情 →</a></div></div></article>`;}
function listMarkup(list){
 if(!list.length)return '<div class="empty-state"><h2>没有匹配结果</h2><p>更换关键词或清空筛选。</p><button class="outline-button" data-action="reset">清空筛选</button></div>';
 const counts=new Map();for(const item of list)counts.set(itemDate(item),(counts.get(itemDate(item))||0)+1);let previous='';
 return list.map(item=>{const value=itemDate(item);const heading=value!==previous?`<div class="day-label"><span class="year">${value.slice(0,4)}</span><time datetime="${value}">${shortDate(value)}</time><span class="date-rule"></span><span class="day-count">${counts.get(value)} 条</span></div>`:'';previous=value;return heading+article(item);}).join('')+`<div class="results-caption">共 ${list.length} 条</div>`;
}
function feedPage(r){const title={feed:'最新情报',incidents:'事件档案',research:'研究披露'}[r.view];const list=filterItems(items,r,read,meta.updatedAt);return `<div class="reading-layout">${sourceSidebar(r)}<section class="content-column"><div class="sr-only"><h1>${title}</h1><span id="result-count" role="status">${list.length} 条情报</span></div>${filters(r)}<div id="news-list" aria-live="polite">${listMarkup(list)}</div></section></div>`;}
function sourcePage(r){const catalog=sources.filter(source=>source.category!=='reference');const text=r.q.toLocaleLowerCase();const list=catalog.filter(source=>[source.name,source.description,source.method,source.notes].join(' ').toLocaleLowerCase().includes(text));const groups={vendor:'厂商与官方披露',research:'AI 安全研究',security:'安全机构',chinese:'中文资料',database:'结构化资料'};return `<div class="page-heading"><h1>来源库</h1><span class="result-count">${catalog.length} 个来源</span></div><div class="source-tools"><label class="search-box" for="source-search">${icon('search')}<input type="search" id="source-search" placeholder="搜索来源…" aria-label="搜索来源" value="${esc(r.q)}"></label><span>入口核验 ${date(meta.updatedAt)} · 定时采集待接入</span></div>${Object.entries(groups).map(([key,name])=>{const group=list.filter(source=>source.category===key);if(!group.length)return '';return `<section class="source-group"><h2 class="source-group-heading">${name}<small>${group.length}</small></h2><div class="source-grid">${group.map(source=>`<article class="source-entry"><div class="source-entry-header"><h3>${esc(source.name)}</h3><span class="method-label">${esc(source.method.toUpperCase())}</span></div><p>${esc(source.description)}</p><div class="source-status ${source.status==='reference'?'reference':''}">${source.status==='checked'?'公开入口已核验':'参考资料'} · ${date(source.checkedAt)}</div><div class="source-entry-links">${safeUrl(source.url)?`<a href="${safeUrl(source.url)}" target="_blank" rel="noopener noreferrer">访问来源 ${icon('external')}</a>`:''}${safeUrl(source.endpoint)?`<a href="${safeUrl(source.endpoint)}" target="_blank" rel="noopener noreferrer">获取入口 ${icon('external')}</a>`:''}${items.some(item=>item.sourceId===source.id)?`<a href="#/feed?source=${source.id}">已收录 ${items.filter(item=>item.sourceId===source.id).length} 条 →</a>`:''}</div><details class="source-details"><summary>接入说明</summary><p>${esc(source.notes)}</p></details></article>`).join('')}</div></section>`;}).join('')}${!list.length?'<div class="empty-state"><h2>没有匹配来源</h2><button class="outline-button" data-action="reset">清空搜索</button></div>':''}`;}
function detailPage(id){
 const item=items.find(value=>value.id===id);if(!item)return notFound();rememberRead(id);
 const refs=item.references.filter(ref=>safeUrl(ref.url));const related=items.filter(value=>value.id!==id&&value.evidence==='primary'&&value.tags.some(tag=>item.tags.includes(tag))).slice(0,2);
 return `<div class="back-row"><a class="back-link" href="${esc(returnHash)}">${icon('back')}返回列表</a><button class="outline-button" data-action="share" data-id="${esc(id)}">${icon('share')}复制链接</button></div><div class="detail-layout"><article class="detail-main">${metadata(item,{withDate:true})}<h1>${esc(item.title)}</h1><div class="item-tags">${tags(item)}</div>${item.externalId?`<p class="detail-id">${esc(item.externalId)}</p>`:''}<p class="detail-deck">${esc(item.summary)}</p><section class="evidence-box"><h2>证据与边界</h2><p>${esc(item.limitations)}</p></section><section class="detail-section"><h2>已披露的影响</h2><p>${esc(item.impact)}</p></section><section class="detail-section"><h2>处置与关注</h2><p>${esc(item.recommendation)}</p></section><section class="detail-section"><h2>原始来源</h2>${refs.map(ref=>`<a class="reference-link" href="${safeUrl(ref.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(ref.label)} ↗</strong><span>${esc(new URL(ref.url).hostname)}</span></a>`).join('')}${item.pdfPage?`<p class="pdf-reference">《2026年10月人工智能安全事件一览》第 ${Number(item.pdfPage)} 页 · ${esc(item.externalId)}</p>`:''}${!refs.length?'<p class="pdf-reference">PDF 汇编未附公开原始链接，原文待补。</p>':''}</section></article><aside class="detail-rail"><h2>资料信息</h2><dl class="detail-dl"><div><dt>披露来源</dt><dd>${esc(item.sourceName)}</dd></div><div><dt>原始披露日期</dt><dd>${date(item.originalPublishedAt)}</dd></div><div><dt>事件发生时间</dt><dd>${esc(item.occurredAt||'未披露')}</dd></div><div><dt>风险类别</dt><dd>${riskNames[item.risk]}</dd></div><div><dt>涉及对象</dt><dd>${item.entities.map(esc).join('、')||'未具名'}</dd></div><div><dt>资料状态</dt><dd>${item.evidence==='primary'?'附原始披露':'PDF 汇编，待补原文'}</dd></div></dl></aside></div>${related.length?`<section class="related-section"><h2>相关情报</h2><div class="related-grid">${related.map(value=>`<article class="related-item">${metadata(value)}<h3><a href="${itemUrl(value)}">${esc(value.title)}</a></h3></article>`).join('')}</div></section>`:''}`;
}
function aboutPage(){return `<div class="page-heading"><h1>收录说明</h1></div><div class="about-copy"><section><h2>内容</h2><p>整理与 AI 模型、智能体及其工具链直接相关的安全事件、漏洞公告和攻击研究。当前共 ${items.length} 条记录，${items.filter(item=>item.evidence==='primary').length} 条附原始披露。</p><p>真实事件、受控研究和漏洞公告分别标注；实验成功不等于存在在野受害者。AI 归因、修复状态与影响范围按原始来源的实际限定记录。</p></section><section><h2>资料与时间</h2><p>本期整理日期 ${date(meta.updatedAt)}。按原始披露日期归档，事件发生时间单独保存；未知日期保留未知。当前为整理后的资料快照，尚未开启定时采集。</p><p>本地 PDF 的 16 条记录保留原 AISID 编号。重复事件合并来源，不重复计数。未补到原文的条目标为 PDF 汇编。</p></section><section><h2>来源与框架</h2><p>原始内容归各作者与机构所有，本站提供中文整理及原文链接。来源分级和事件整理流程参考 <a href="https://github.com/KKKKhazix/AIHOT" target="_blank" rel="noopener noreferrer">AIHOT</a>；阅读布局参考 <a href="https://get-anthropic.vercel.app/" target="_blank" rel="noopener noreferrer">Anthropic 资讯日报</a>。</p><p>入口核验表示可访问且格式可解析，不代表持续采集已经运行。已读状态仅保存在当前浏览器。</p></section></div>`;}
function notFound(){return '<div class="empty-state"><h2>没有找到这条资料</h2><a class="outline-button" href="#/feed">返回最新情报 →</a></div>';}
function render(preserveFocus=false){
 const active=document.activeElement;const focusId=preserveFocus?active?.id:null;const cursor=preserveFocus&&active instanceof HTMLInputElement?active.selectionStart:null;
 const oldDetails=document.querySelector('.filter-panel');if(oldDetails)filtersOpen=oldDetails.open;
 const r=route();document.querySelectorAll('[data-nav]').forEach(link=>{const current=link.dataset.nav===r.view;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 const nav=document.querySelector('.nav-links');const selected=nav.querySelector('[aria-current]');if(selected){const a=selected.getBoundingClientRect(),b=nav.getBoundingClientRect();if(a.right>b.right)nav.scrollLeft+=a.right-b.right+8;else if(a.left<b.left)nav.scrollLeft-=b.left-a.left+8;}
 const titles={feed:'最新情报',incidents:'事件档案',research:'研究披露',sources:'来源库',about:'收录说明'};
 document.title=`${r.view==='item'?(items.find(item=>item.id===r.id)?.title||'情报详情'):(titles[r.view]||'页面未找到')} | AI 安全观察`;
 document.querySelector('#edition-date').textContent=date(meta.updatedAt);
 main.innerHTML=['feed','incidents','research'].includes(r.view)?feedPage(r):r.view==='sources'?sourcePage(r):r.view==='item'?detailPage(r.id):r.view==='about'?aboutPage():notFound();
 if(focusId){const target=document.getElementById(focusId);target?.focus({preventScroll:true});if(cursor!==null&&target?.type==='search')try{target.setSelectionRange(cursor,cursor);}catch{}}
}
document.addEventListener('pointerdown',()=>inputMethod='pointer');document.addEventListener('keydown',()=>inputMethod='keyboard');
document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView();return;}
 const button=event.target.closest('[data-action]');if(!button)return;
 if(button.dataset.action==='source')setParam('source',button.dataset.value);
 else if(button.dataset.action==='topic')setParam('topic',button.dataset.value);
 else if(button.dataset.action==='reset')reset();
 else if(button.dataset.action==='risk-reset')setParam('risk','all');
 else if(button.dataset.action==='share'){
  const url=new URL(location.href);url.hash=`/item/${encodeURIComponent(button.dataset.id)}`;
  try{await navigator.clipboard.writeText(url.href);toast('链接已复制');}catch{toast('可从浏览器地址栏复制链接');}
 }
});
document.addEventListener('change',event=>{if(event.target.matches('[data-filter]'))setParam(event.target.dataset.filter,event.target.value);if(event.target.id==='unread-toggle')setParam('unread',event.target.checked?'1':'0');});
document.addEventListener('input',event=>{if(['search-input','source-search'].includes(event.target.id)){const value=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>setParam('q',value,{replace:true}),180);}});
document.addEventListener('submit',event=>{if(event.target.id==='filter-form'){event.preventDefault();clearTimeout(searchTimer);setParam('q',document.querySelector('#search-input').value,{replace:true});}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)){const input=document.querySelector('#search-input,#source-search');if(input){event.preventDefault();input.focus();}}if(event.key==='Escape'&&event.target.matches('#search-input,#source-search')){clearTimeout(searchTimer);setParam('q','',{replace:true});}});
window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);const previous=lastHash;lastHash=location.hash;const previousView=previous.replace(/^#\/?/,'').split(/[/?]/)[0];const current=route();if(current.view==='item'&&previousView!=='item')returnHash=previous;render();if(previousView!==current.view){window.scrollTo({top:0});if(inputMethod==='keyboard')main.focus({preventScroll:true});}});
window.addEventListener('storage',event=>{if(event.key==='ai-security-observer:v1:read'){read.clear();loadRead().forEach(id=>read.add(id));render();}});
try{
 const responses=await Promise.all([fetch('./data/items.json'),fetch('./data/sources.json')]);if(responses.some(response=>!response.ok))throw new Error('资料读取失败');
 const [data,catalog]=await Promise.all(responses.map(response=>response.json()));items=data.items;sources=catalog;meta=data.meta;render();
}catch(error){main.innerHTML='<div class="empty-state"><h2>暂时无法载入资料</h2><p>请刷新页面重试。</p><button class="outline-button" id="reload-button">重新加载</button></div>';document.querySelector('#reload-button').addEventListener('click',()=>location.reload());console.error(error);}
